'use strict';

// MODULES //

var hasOwnProp = require( '@stdlib/assert/has-own-property' );


// VARIABLES //

var SYMBOLS = {
	'arrow': '->',
	'->': '->',

	'asterisk': '*',
	'*': '*',

	'circle': 'o',
	'o': 'o',

	'cross': '+',
	'plus': '+',
	'+': '+',

	'diamond': 'd',
	'd': 'd',

	'dot': '.',
	'.': '.',

	'hexagram': 'h',
	'h': 'h',

	'line': '|',
	'|': '|',

	'square': 's',
	's': 's',

	'star': 'p',
	'pentagram': 'p',
	'p': 'p',

	'stroke': '_',
	'_': '_',

	'triangle': 't',
	't': 't',

	'triangle-down': 'v',
	'v': 'v',

	'triangle-left': '<',
	'<': '<',

	'triangle-right': '>',
	'>': '>',

	'triangle-up': '^',
	'^': '^',

	'wedge': 'w',
	'w': 'w',

	'x': 'x'
};


// MAIN //

/**
* Converts a symbol alias or shorthand to a symbol shorthand.
*
* ## Notes
*
* -   If provided a shorthand, the function returns the provided shorthand.
* -   If unable to resolve a shorthand, the function returns `null`.
*
* @param {string} value - symbol alias or shorthand
* @returns {(string|null)} symbol shorthand
*
* @example
* var v = symbol2shorthand( 'circle' );
* // returns 'o'
*
* v = symbol2shorthand( 'o' );
* // returns 'o'
*
* v = symbol2shorthand( 'beep' );
* // returns null
*/
function symbol2shorthand( value ) {
	if ( hasOwnProp( SYMBOLS, value ) ) {
		return SYMBOLS[ value ];
	}
	return null;
}


// EXPORTS //

module.exports = symbol2shorthand;
